import{_ as s,C as t,o as a,c as r,a2 as o,b as n,w as l,a as c,E as d,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const f=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_4.md"}'),m={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_4.md"};function p(b,e,g,q,v,E){const i=t("Mermaid");return a(),r("div",null,[e[1]||(e[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-principios-del-enfoque-del-marco-logico-eml" tabindex="-1">Eje Temático: Principios del Enfoque del Marco Lógico (EML) <a class="header-anchor" href="#eje-tematico-principios-del-enfoque-del-marco-logico-eml" aria-label="Permalink to &quot;Eje Temático: Principios del Enfoque del Marco Lógico (EML)&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-ingenieria-de-proyectos" tabindex="-1">🧭 Introducción: La Ingeniería de Proyectos <a class="header-anchor" href="#🧭-introduccion-la-ingenieria-de-proyectos" aria-label="Permalink to &quot;🧭 Introducción: La Ingeniería de Proyectos&quot;">​</a></h2><p>Imagina intentar construir un edificio sin planos. Empezarías a poner ladrillos donde se te ocurra, olvidarías las tuberías del agua, y eventualmente, la casa colapsaría. En la gestión de proyectos informáticos y sociales ocurre lo mismo.</p><p>El <strong>Enfoque del Marco Lógico (EML)</strong> es tu &quot;plano arquitectónico&quot;. Es una metodología de planificación de proyectos a nivel internacional (usada por la ONU, el Banco Interamericano de Desarrollo y exigida en los PNF de Venezuela) que te obliga a pensar de manera sistemática y lógica antes de gastar un solo bolívar o escribir una sola línea de código.</p><hr><h2 id="🏛️-capitulo-i-¿que-es-el-enfoque-del-marco-logico" tabindex="-1">🏛️ CAPÍTULO I: ¿Qué es el Enfoque del Marco Lógico? <a class="header-anchor" href="#🏛️-capitulo-i-¿que-es-el-enfoque-del-marco-logico" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: ¿Qué es el Enfoque del Marco Lógico?&quot;">​</a></h2><p>El EML no es un documento o una simple tabla; es un <strong>proceso de pensamiento</strong>. Es una herramienta que facilita el proceso de conceptualización, diseño, ejecución y evaluación de proyectos.</p><p>Su principal virtud es que alinea perfectamente los problemas de la comunidad con las soluciones tecnológicas que tú vas a proponer. Evita que construyas &quot;puentes donde no hay ríos&quot; asegurando que cada actividad que realices tenga una razón de ser y un objetivo claro.</p><h3 id="_1-1-el-ciclo-del-proyecto-bajo-el-eml" tabindex="-1">1.1 El Ciclo del Proyecto bajo el EML <a class="header-anchor" href="#_1-1-el-ciclo-del-proyecto-bajo-el-eml" aria-label="Permalink to &quot;1.1 El Ciclo del Proyecto bajo el EML&quot;">​</a></h3><p>El EML concibe la vida de un proyecto como un ciclo continuo, dividido en fases estructuradas (las cuales coinciden con la estructura del PSI/T):</p><ol><li><strong>Identificación:</strong> (Lo que acabamos de hacer con el Diagnóstico Participativo). Descubrir cuál es el problema.</li><li><strong>Formulación (Diseño):</strong> Traducir el problema en objetivos, actividades y presupuesto (Lo que haremos con el EML).</li><li><strong>Ejecución y Seguimiento:</strong> Poner manos a la obra (Soporte técnico, talleres) verificando que vayamos según el plan.</li><li><strong>Evaluación:</strong> Al final del proyecto, medir si realmente logramos resolver el problema inicial.</li></ol><h3 id="_1-2-representacion-visual-del-ciclo-eml" tabindex="-1">1.2 Representación Visual del Ciclo EML <a class="header-anchor" href="#_1-2-representacion-visual-del-ciclo-eml" aria-label="Permalink to &quot;1.2 Representación Visual del Ciclo EML&quot;">​</a></h3>',15)),(a(),n(u,null,{default:l(()=>[d(i,{id:"mermaid-60",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A(1.%20Identificaci%C3%B3n)%20--%3E%20B(2.%20Formulaci%C3%B3n)%0A%20%20%20%20B%20--%3E%20C(3.%20Ejecuci%C3%B3n)%0A%20%20%20%20C%20--%3E%20D(4.%20Evaluaci%C3%B3n)%0A%20%20%20%20D%20-.%20Retroalimentaci%C3%B3n%20.-%3E%20A%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23ffcc99%2Cstroke%3A%23ff6600%0A%20%20%20%20style%20B%20fill%3A%2399ccff%2Cstroke%3A%230066cc%0A%20%20%20%20style%20C%20fill%3A%2399ff99%2Cstroke%3A%23009900%0A%20%20%20%20style%20D%20fill%3A%23e6b3ff%2Cstroke%3A%239900cc%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<hr><h2 id="🧩-capitulo-ii-las-fases-metodologicas-del-eml" tabindex="-1">🧩 CAPÍTULO II: Las Fases Metodológicas del EML <a class="header-anchor" href="#🧩-capitulo-ii-las-fases-metodologicas-del-eml" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Las Fases Metodológicas del EML&quot;">​</a></h2><p>El EML se desarrolla paso a paso, como una escalera. No puedes saltarte escalones.</p><h3 id="paso-1-analisis-de-involucrados" tabindex="-1">Paso 1: Análisis de Involucrados <a class="header-anchor" href="#paso-1-analisis-de-involucrados" aria-label="Permalink to &quot;Paso 1: Análisis de Involucrados&quot;">​</a></h3><p>Ya lo hicimos en la evaluación anterior. Consiste en mapear quiénes están a favor, quiénes en contra y a quiénes afecta el proyecto. Si no tomas en cuenta a los usuarios del sistema que vas a reparar, boicotearán tu trabajo.</p><h3 id="paso-2-analisis-de-problemas-el-arbol-de-problemas" tabindex="-1">Paso 2: Análisis de Problemas (El Árbol de Problemas) <a class="header-anchor" href="#paso-2-analisis-de-problemas-el-arbol-de-problemas" aria-label="Permalink to &quot;Paso 2: Análisis de Problemas (El Árbol de Problemas)&quot;">​</a></h3><p>Es la fase de descubrir la &quot;raíz&quot; del asunto. Se dibuja literalmente como un árbol.</p><ul><li><strong>El Tronco:</strong> Es el problema central que descubriste en el diagnóstico (Ej: &quot;Alta inoperatividad de los equipos de computación del liceo&quot;).</li><li><strong>Las Raíces (Causas):</strong> Por qué ocurre el problema (Ej: &quot;Falta de mantenimiento preventivo&quot;, &quot;Desconocimiento técnico del personal&quot;, &quot;Fallas eléctricas&quot;).</li><li><strong>Las Ramas (Efectos):</strong> Las consecuencias sociales del problema (Ej: &quot;Atraso en los procesos administrativos&quot;, &quot;Alumnos sin acceso a las TIC&quot;).</li></ul><h3 id="paso-3-analisis-de-objetivos-el-arbol-de-objetivos" tabindex="-1">Paso 3: Análisis de Objetivos (El Árbol de Objetivos) <a class="header-anchor" href="#paso-3-analisis-de-objetivos-el-arbol-de-objetivos" aria-label="Permalink to &quot;Paso 3: Análisis de Objetivos (El Árbol de Objetivos)&quot;">​</a></h3><p>Es el &quot;espejo positivo&quot; del paso anterior. Todo lo negativo del Árbol de Problemas se reescribe como algo positivo y deseable.</p><ul><li>El problema central se vuelve el <strong>Objetivo General</strong> (Ej: &quot;Equipos de computación del liceo 100% operativos&quot;).</li><li>Las causas se vuelven los <strong>Medios</strong> (Ej: &quot;Mantenimiento preventivo ejecutado&quot;, &quot;Personal capacitado&quot;).</li><li>Los efectos se vuelven los <strong>Fines</strong> (Ej: &quot;Procesos administrativos ágiles&quot;).</li></ul><h3 id="paso-4-analisis-de-alternativas" tabindex="-1">Paso 4: Análisis de Alternativas <a class="header-anchor" href="#paso-4-analisis-de-alternativas" aria-label="Permalink to &quot;Paso 4: Análisis de Alternativas&quot;">​</a></h3><p>Un mismo problema puede tener varias soluciones. Si las computadoras están dañadas, la alternativa 1 es comprar nuevas (altísimo costo), la alternativa 2 es repararlas ustedes mismos (bajo costo, alto impacto de aprendizaje). Aquí se escoge la estrategia más viable.</p><h3 id="paso-5-la-matriz-del-marco-logico-mml" tabindex="-1">Paso 5: La Matriz del Marco Lógico (MML) <a class="header-anchor" href="#paso-5-la-matriz-del-marco-logico-mml" aria-label="Permalink to &quot;Paso 5: La Matriz del Marco Lógico (MML)&quot;">​</a></h3><p>Es el producto final del EML. Es una tabla resumen de 4 filas y 4 columnas que contiene ABSOLUTAMENTE TODO el diseño del proyecto de manera resumida:</p><ul><li><strong>Fin:</strong> El impacto a largo plazo en la sociedad.</li><li><strong>Propósito:</strong> El objetivo central de tu proyecto.</li><li><strong>Componentes (Resultados):</strong> Los entregables (Los equipos arreglados, los manuales entregados).</li><li><strong>Actividades:</strong> Las tareas a realizar (limpiar hardware, instalar software).</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Importancia Institucional</strong> Dominar el EML no solo te servirá para aprobar el Trayecto I. El reglamento del PSI/T y las normativas metodológicas de la UPTT basan la estructura de tu <strong>Informe Final</strong> (Capítulo II y III) enteramente en la lógica del EML. Si dominas los árboles de problemas y objetivos ahora, el resto del año será un simple paseo en bajada.</p></div><p>Con esto cerramos el <strong>Trimestre 1</strong>. Ya sabemos abordar a la comunidad, realizar diagnósticos participativos y conocemos la teoría del EML. En el próximo trimestre, aplicaremos todo esto de forma práctica formulando formalmente tu proyecto sociotecnológico.</p>',18))])}const P=s(m,[["render",p]]);export{f as __pageData,P as default};
